using System.Collections.Generic;

/// <summary>Acts III-V: subtitle text and speaker for every voiced line (the audio is Resources/VO/&lt;id&gt;.wav).</summary>
public static class DialogueDB
{
    static readonly Dictionary<string, string[]> lines = new Dictionary<string, string[]>
    {
        {"a3_vo_intro", new[] { "ARJUN (V.O.)", "The Old Chandnipur Library. Two hundred years of the city's memory, locked up for the night. If Priya found the truth anywhere, she found it here." }},
        {"a3_sharma_1", new[] { "SHARMA-JI", "Library is closed, sahib. Nine o'clock means closed. Who are you?" }},
        {"a3_arjun_letter", new[] { "ARJUN", "Arjun Mehra. Kamala Kapoor sent me. Here is her letter." }},
        {"a3_sharma_2", new[] { "SHARMA-JI", "Kamala-ji's daughter... Priya madam used to sit here till midnight with her files. Go in, sahib. The computer at the front desk still works. And the record room is downstairs. She spent many nights down there." }},
        {"a3_arjun_usb", new[] { "ARJUN", "Vikram's USB drive. Let's see what Priya was hiding." }},
        {"a3_arjun_backup", new[] { "ARJUN", "Priya kept a backup of her research on this machine. She would have locked it." }},
        {"a3_arjun_pass", new[] { "ARJUN", "Encrypted. Her diary said: where it all began for us, the year Nani told us stories. Kamala-ji sent me a photo of the children at their grandmother's house." }},
        {"a3_audio", new[] { "RECORDING", "the hearing is Thursday... make sure the originals are destroyed... Reddy is getting too close..." }},
        {"a3_arjun_unlock", new[] { "ARJUN", "This is it. The smoking gun. The Renewal Project is built on a lie. And someone named Reddy is involved. The same Reddy whose ID I found in the market." }},
        {"a3_arjun_basement", new[] { "ARJUN", "Block C, Shelf 14, the years 1940 to 1945. That is where Priya said the original deed would be." }},
        {"a3_arjun_cage", new[] { "ARJUN", "Locked. A wire cage and a padlock. The key has to be somewhere in this building." }},
        {"a3_arjun_calendar", new[] { "ARJUN", "Three dates circled in red. Independence Day, Republic Day, Gandhi Jayanti. Someone wanted to remember 1947. Backwards, maybe." }},
        {"a3_arjun_desk", new[] { "ARJUN", "The librarian's desk. A four digit lock on the drawer." }},
        {"a3_arjun_key", new[] { "ARJUN", "A small brass key. The cage key, I would bet." }},
        {"a3_arjun_empty", new[] { "ARJUN", "The 1942 folder. It's empty. Just a sign-out sheet." }},
        {"a3_arjun_reddy", new[] { "ARJUN", "Inspector Reddy took the original deed. Is she destroying evidence for Deshpande? Or is she building a case of her own? I need to find out." }},
        {"a3_vo_temple", new[] { "ARJUN (V.O.)", "The Kali Temple. Priya told Vikram that Kali Ma would protect the truth. Maybe she meant it more literally than he thought." }},
        {"a3_pandit_1", new[] { "HARISHANKAR", "You are looking for Priya. I can see it in your eyes. You have the same look she had when she came to me. Desperate, and determined." }},
        {"a3_arjun_q", new[] { "ARJUN", "She left something with you?" }},
        {"a3_pandit_2", new[] { "HARISHANKAR", "She did. A sealed envelope. She said someone would come for it, but she also said I should only give it to someone who understands what matters." }},
        {"a3_ans_a", new[] { "ARJUN", "The truth. Always. Without truth, there is no justice." }},
        {"a3_ans_b", new[] { "ARJUN", "The people. Truth is meaningless if it doesn't serve those who suffer." }},
        {"a3_ans_c", new[] { "ARJUN", "They're the same thing. The truth protects the people, and the people deserve the truth." }},
        {"a3_pandit_a", new[] { "HARISHANKAR", "A journalist's answer. Very well." }},
        {"a3_pandit_b", new[] { "HARISHANKAR", "A compassionate answer. Priya would agree." }},
        {"a3_pandit_c", new[] { "HARISHANKAR", "Now, that is the answer she hoped for." }},
        {"a3_letter", new[] { "PRIYA (LETTER)", "If you're reading this, I hope you're someone I can trust. The councilor, the builder, and someone in the police are all connected. The hearing is tomorrow morning at ten, at the Municipal Court. Five hundred families are counting on this. I'm trusting you with their futures. Please don't let me down. Priya." }},
        {"a3_caller", new[] { "UNKNOWN CALLER", "Mr. Mehra. You've been busy tonight. I must say, I'm impressed. Most people would have given up after the apartment. But you've gone further, and that makes you either very brave, or very foolish." }},
        {"a3_vo_crossroads", new[] { "ARJUN (V.O.)", "Two calls, and time for one. Or I could stop running, and call the one person who keeps turning up in this story." }},
        {"a3_vo_end", new[] { "ARJUN (V.O.)", "Every choice closes a door. In Chandnipur, closed doors have a way of locking behind you." }},
        {"a4a_vo", new[] { "ARJUN (V.O.)", "Café Irani. Checked tablecloths, Osmania biscuits, and at this hour, nobody who wants to be seen." }},
        {"a4a_raj_1", new[] { "RAJ MALHOTRA", "Sit down, Mr. Mehra. And before you say anything, yes, I know who I am. I'm the villain of this story. The big bad builder who wants to demolish a slum. That's what the newspapers will say. That's what Priya Kapoor believes. And she's not entirely wrong." }},
        {"a4a_arjun_why", new[] { "ARJUN", "Then why did you call me?" }},
        {"a4a_raj_2", new[] { "RAJ MALHOTRA", "Because I'm in over my head. And I think you're the only person in this city who isn't on Deshpande's payroll. I didn't know the land documents were forged, I swear it. By the time I found out, when Priya started making noise about the original deed, I was already in too deep. Deshpande had recordings of me discussing the project with her. She had financial records showing my company receiving advance payments from government funds. If I backed out, she'd destroy me. If I stayed, I'd be complicit in displacing five hundred families." }},
        {"a4a_q_a", new[] { "ARJUN", "Why should I trust you?" }},
        {"a4a_raj_a", new[] { "RAJ MALHOTRA", "You shouldn't. Not yet. But I'm going to give you something that should earn a little trust." }},
        {"a4a_q_b", new[] { "ARJUN", "Where is Priya?" }},
        {"a4a_raj_b", new[] { "RAJ MALHOTRA", "I know where she is. I've known for twenty four hours. My people were tracking her. Deshpande ordered it, but I haven't told her. I told my men she'd gone to Nagpur. That bought Priya some time. She's at the old NGO shelter near the river. The school building." }},
        {"a4a_q_c", new[] { "ARJUN", "What do you want in return?" }},
        {"a4a_raj_c", new[] { "RAJ MALHOTRA", "Immunity. I'll testify against Deshpande. I'll give you the recordings, the financial records, everything. But I want my name kept out of the criminal case. I have a family, Mr. Mehra. I have a daughter Priya's age. I don't want to spend the rest of my life in prison for a crime I was manipulated into." }},
        {"a4a_raj_made", new[] { "RAJ MALHOTRA", "We've been made. Back door. Now." }},
        {"a4a_arjun_kitchen", new[] { "ARJUN", "The kitchen. Pots everywhere. Quietly." }},
        {"a4a_raj_clang", new[] { "RAJ MALHOTRA", "That was close. Slowly now. Keep the rack and the sacks between us and that torch." }},
        {"a4a_raj_wait", new[] { "RAJ MALHOTRA", "Wait. Don't move." }},
        {"a4a_searcher_listen", new[] { "DESHPANDE'S MAN", "Who's there? Hm." }},
        {"a4a_searcher_found", new[] { "DESHPANDE'S MAN", "Oi! In the kitchen! Here!" }},
        {"a4a_arjun_dead", new[] { "ARJUN", "Dead end. Back to the fork." }},
        {"a4a_arjun_hide", new[] { "ARJUN", "Footsteps. Behind the dumpster, now!" }},
        {"a4a_thug_search", new[] { "DESHPANDE'S MAN", "They came this way. Check the alley. The councilor wants them both." }},
        {"a4a_caught", new[] { "DESHPANDE'S MAN", "There! In the alley!" }},
        {"a4a_raj_where", new[] { "RAJ MALHOTRA", "I know where she is. I've known for twenty four hours. My people were tracking her. Deshpande ordered it, but I haven't told her. I told my men she'd gone to Nagpur. That bought Priya some time. She's at the old NGO shelter near the river. The school building." }},
        {"a4a_raj_dhaba", new[] { "RAJ MALHOTRA", "Tomorrow morning. The hearing. I'll be there. Make sure Priya is there too." }},
        {"a4a_vo_end", new[] { "ARJUN (V.O.)", "A frightened builder with a phone full of recordings. In this city, that's the closest thing to an army." }},
        {"a4b_vo", new[] { "ARJUN (V.O.)", "The Kapoor house. The front door was open. That's never a good sign." }},
        {"a4b_kamala_1", new[] { "KAMALA KAPOOR", "They came an hour ago. Two men. They said they were from the Municipal Office, looking for misplaced documents. When I told them I didn't have any documents, they pushed past me and tore the house apart. They were looking for something specific. They kept asking about a file, and a deed." }},
        {"a4b_arjun_find", new[] { "ARJUN", "Did they find anything?" }},
        {"a4b_kamala_2", new[] { "KAMALA KAPOOR", "No. Whatever they wanted, it wasn't here." }},
        {"a4b_arjun_print", new[] { "ARJUN", "A muddy boot print. Heavy boots. These weren't clerks." }},
        {"a4b_arjun_pass", new[] { "ARJUN", "A visitor pass from the Municipal Office. One of them dropped it." }},
        {"a4b_arjun_laptop", new[] { "ARJUN", "Rohan's laptop. Still logged into his Municipal Office email. An intern shouldn't be able to see these." }},
        {"a4b_arjun_confront", new[] { "ARJUN", "Rohan. These emails. How do you have them?" }},
        {"a4b_rohan_1", new[] { "ROHAN KAPOOR", "It's my fault. All of it. I am the one who found the forged documents. I was filing papers at the office, boring intern work, and I saw the original acquisition order. Something didn't look right. The dates didn't match. The signatures were different. I compared it with the public records and realised the whole thing was fake." }},
        {"a4b_arjun_told", new[] { "ARJUN", "And you told Priya?" }},
        {"a4b_rohan_2", new[] { "ROHAN KAPOOR", "She is my sister. Of course I told her. I thought she'd file a complaint, go through proper channels. And now Deshpande's people are hunting her, and it's because of me." }},
        {"a4b_q_a", new[] { "ARJUN", "Can you take me to her?" }},
        {"a4b_rohan_a", new[] { "ROHAN KAPOOR", "Yes. I've been in contact with her. She's at the old NGO shelter near the river. She made me promise not to tell anyone, but I think she needs help now. I'll take you." }},
        {"a4b_q_b", new[] { "ARJUN", "We need to go to the police." }},
        {"a4b_rohan_b", new[] { "ROHAN KAPOOR", "The police? Arjun-ji, the police are part of the problem. Deshpande has officers on her payroll. The only cop I trust is Inspector Reddy, and I don't even know whose side she's on." }},
        {"a4b_q_c", new[] { "ARJUN", "We need to protect these documents first." }},
        {"a4b_rohan_c", new[] { "ROHAN KAPOOR", "I have copies of everything on the cloud drive. The emails, the forged orders, the comparison analysis. Even if they destroy the physical copies, the digital evidence is safe." }},
        {"a4b_kamala_3", new[] { "KAMALA KAPOOR", "Bring her home, Arjun. Please. Both of you, come back safe." }},
        {"a4b_vo_end", new[] { "ARJUN (V.O.)", "A guilty brother and a cloud drive full of emails. Sometimes the truth hides in the most ordinary places." }},
        {"a4c_vo", new[] { "ARJUN (V.O.)", "Chandnipur Police Station. Half the city's secrets end up here. The other half start here." }},
        {"a4c_reddy_1", new[] { "INSPECTOR REDDY", "Mr. Mehra. I was wondering when you'd figure out I was following you. You're better than I expected." }},
        {"a4c_arjun_id", new[] { "ARJUN", "You dropped your ID in the market. Not very undercover." }},
        {"a4c_reddy_2", new[] { "INSPECTOR REDDY", "Maybe I wanted you to notice. Sit down. We need to talk." }},
        {"a4c_reddy_r1", new[] { "INSPECTOR REDDY", "I don't know any Priya Kapoor. I'm a crime branch officer. Organised crime, not missing persons." }},
        {"a4c_reddy_r1ok", new[] { "INSPECTOR REDDY", "Alright. You've done your homework. Yes, I know the Kapoor case. It's connected to an ongoing investigation. I can't share details." }},
        {"a4c_reddy_wrong", new[] { "INSPECTOR REDDY", "That proves nothing, Mr. Mehra. Try harder, or go home." }},
        {"a4c_reddy_sig", new[] { "INSPECTOR REDDY", "That's my signature." }},
        {"a4c_weak1_usb", new[] { "INSPECTOR REDDY", "Priya's research. It shows what she found. It doesn't put me anywhere near her." }},
        {"a4c_weak1_clip", new[] { "INSPECTOR REDDY", "Newspaper cuttings. Half the city has read those. They don't connect me to her." }},
        {"a4c_weak1_plate", new[] { "INSPECTOR REDDY", "A number plate. Find out whose car it is before you bring it to me. It isn't mine." }},
        {"a4c_weak1_bhaskar", new[] { "INSPECTOR REDDY", "An auto driver saw a black car. That's a rumour, not a link to me." }},
        {"a4c_weak2_id", new[] { "INSPECTOR REDDY", "You've made that point. My card tells you who I am, not what you know." }},
        {"a4c_weak2_signout", new[] { "INSPECTOR REDDY", "I know what I signed. That isn't the question now." }},
        {"a4c_weak2_plate", new[] { "INSPECTOR REDDY", "A car in a lane. It shows someone followed you. It doesn't show you understand what this is." }},
        {"a4c_weak2_bhaskar", new[] { "INSPECTOR REDDY", "A driver heard a car. That isn't a case, Mr. Mehra." }},
        {"a4c_reddy_r2", new[] { "INSPECTOR REDDY", "My investigation is classified. You're seeing a fraction of the picture. Stay out of it." }},
        {"a4c_reddy_r2ok", new[] { "INSPECTOR REDDY", "Where did you get that? Never mind. I can see you're not going to stop. Fine. Let me tell you what you don't know." }},
        {"a4c_reddy_r3", new[] { "INSPECTOR REDDY", "You think I took the original deed to destroy it for Deshpande. That's what it looks like, isn't it?" }},
        {"a4c_q_a", new[] { "ARJUN", "I have evidence you don't." }},
        {"a4c_reddy_a", new[] { "INSPECTOR REDDY", "Then we are both holding half a case. Alright, Mr. Mehra. Cards on the table." }},
        {"a4c_q_b", new[] { "ARJUN", "Are you protecting Deshpande, or investigating her?" }},
        {"a4c_reddy_b", new[] { "INSPECTOR REDDY", "Investigating her. For six months. I'm undercover. I took the original deed as evidence. It's locked in a secure evidence room right now." }},
        {"a4c_q_c", new[] { "ARJUN", "Priya's life is in danger. Politics can wait." }},
        {"a4c_reddy_c", new[] { "INSPECTOR REDDY", "You're right. I've been so focused on building the perfect case that I almost lost sight of the person at the centre of it. Let me help." }},
        {"a4c_reddy_reveal", new[] { "INSPECTOR REDDY", "I've been protecting Priya for two weeks. My men are watching the NGO shelter by the river. I have the deed, the financial records, the witnesses. I need one more thing. I need Priya to testify in person." }},
        {"a4c_vo_end", new[] { "ARJUN (V.O.)", "An honest cop in Chandnipur. I'd almost stopped believing in them." }},
        {"a5_vo_intro", new[] { "ARJUN (V.O.)", "The old school by the river. Four in the morning. Somewhere upstairs, a single lamp is still burning." }},
        {"a5_resident", new[] { "RESIDENT", "Upstairs, bhaiya. Priya didi hasn't slept in days." }},
        {"a5_priya_upstairs", new[] { "PRIYA KAPOOR", "Order number one fourteen, nineteen sixty five. The stamp is from Wardha district. Wardha. Why would Wardha stamp a Chandnipur order..." }},
        {"a5_priya_1", new[] { "PRIYA KAPOOR", "I knew someone would come. I just didn't know if they'd come to help me, or to silence me." }},
        {"a5_arjun_mother", new[] { "ARJUN", "Your mother sent me. She's worried sick." }},
        {"a5_priya_2", new[] { "PRIYA KAPOOR", "Maa... I called her. I told her I loved her. I thought it might be the last time I could say it." }},
        {"a5_priya_3", new[] { "PRIYA KAPOOR", "Five hundred families, Arjun. Children, grandparents, people who've lived in Basti Nagar for generations. The courts, the police, the politicians. They're all part of the same machine. I had to do this myself." }},
        {"a5_priya_4", new[] { "PRIYA KAPOOR", "I have the original 1965 file. The forged one, with their signatures on it. The hearing is in six hours. But if I walk into that courtroom, Deshpande will have me arrested for stealing government property. So tell me, Mr. Mehra. You've seen the evidence. What should I do?" }},
        {"a5_arjun_justice", new[] { "ARJUN", "Walk into that courtroom yourself. Show them the truth. I'll be right beside you, and I'll make sure the whole city sees what happens." }},
        {"a5_arjun_sacrifice", new[] { "ARJUN", "Let me take the evidence in. You stay hidden until it's safe. Your life matters more than any hearing." }},
        {"a5_arjun_revolution", new[] { "ARJUN", "We release everything to the press. Every document, every recording, every email. Let the people of Chandnipur decide." }},
        {"gal_1", new[] { "THE CURATOR", "Ah. There you are. I was beginning to wonder if you'd lost your way in all those narrow lanes, and narrower consciences." }},
        {"gal_2", new[] { "THE CURATOR", "Welcome to my collection. Every object you see is a story. A life, a choice, a consequence. And now, yours. The missing girl. The forged deed. Five hundred families sleeping under tin roofs." }},
        {"gal_3", new[] { "THE CURATOR", "You followed every thread I laid out for you. But investigation is merely the appetiser, my friend. The main course is choice." }},
        {"gal_4", new[] { "THE CURATOR", "Three caskets. Three inscriptions. Three futures. In a play by a certain English bard, a merchant's daughter offered her suitors a similar test. Most chose wrong. I wonder. Will you?" }},
        {"gal_5", new[] { "THE CURATOR", "Step forward. Read the inscriptions. Choose your casket. And remember: in my collection there are no wrong endings. Only consequences." }},
        {"gal_bronze", new[] { "THE CURATOR", "Bronze. The metal of heroes and monuments. Justice, the clean courtroom kind. But read it carefully. A single throat to the wolf. Choose this, and Priya walks into the lion's den." }},
        {"gal_bone", new[] { "THE CURATOR", "Bone. The material of endings. Choose this, and Arjun takes the evidence to court alone. Priya stays hidden. She survives. But sanctuaries built on silence have a way of collapsing." }},
        {"gal_iron", new[] { "THE CURATOR", "Iron. The metal of revolution. Choose this, and the evidence goes to the press. The people rise. But fire does not discriminate, my friend. It burns the guilty and the innocent alike." }},
        {"gal_sealed_bronze", new[] { "THE CURATOR", "Justice demands proof, detective, and your pockets are rather light. The bronze will not open for you." }},
        {"gal_sealed_iron", new[] { "THE CURATOR", "A fire needs fuel. Recordings, emails, something the city can read. You have none. The iron stays cold." }},
        {"gal_chosen", new[] { "THE CURATOR", "So be it." }},
        {"cur0_01", new[] { "THE CURATOR", "There you are." }},
        {"cur0_02", new[] { "THE CURATOR", "You may call me the Curator. Everyone does. It saves time." }},
        {"cur0_03", new[] { "THE CURATOR", "This is not the room you left. This is where the room you left is kept." }},
        {"cur0_04", new[] { "THE CURATOR", "A woman disappears, and the city files her under \"left voluntarily.\" The city is a poor librarian." }},
        {"cur0_05", new[] { "THE CURATOR", "But you did not believe the filing. You walked into a life interrupted mid-sentence. A chai gone cold. A suitcase half-packed. A window forced from the outside." }},
        {"cur0_06", new[] { "THE CURATOR", "You noticed. In my experience, noticing is the rarest courage. It is also the cheapest. Consequently, everyone can afford it, and almost no one buys it." }},
        {"cur0_07", new[] { "THE CURATOR", "You moved through her things like a man reading someone else's diary. Guilty. Careful. Good. Guilt is a form of respect." }},
        {"cur0_08", new[] { "THE CURATOR", "The phone was behind the law books. The law is an excellent place to hide a thing. No one looks behind it." }},
        {"cur0_09", new[] { "THE CURATOR", "The number was under the keyboard. She hid it from the laptop and kept it for a person. Try to be that person." }},
        {"cur0_10", new[] { "THE CURATOR", "A note under the door, in the same hand as the number. Two messages, one author." }},
        {"cur0_11", new[] { "THE CURATOR", "Ask yourself: why would a friend warn you away, and then leave you a thread to pull?" }},
        {"cur0_12", new[] { "THE CURATOR", "I will keep this key. You will not need the door again. You will need the name behind it." }},
        {"cur0_13", new[] { "THE CURATOR", "Someone stood on that landing and listened to you breathe. They did not knock." }},
        {"cur0_14", new[] { "THE CURATOR", "People who do not knock are waiting for something. Do not give it to them." }},
        {"cur0_15", new[] { "THE CURATOR", "Dawn is a creditor, investigator. It always collects. Off you go." }},
        {"cur1_01", new[] { "THE CURATOR", "Chandnipur at night is a sentence written in neon and cooking oil. You read it better than most." }},
        {"cur1_02", new[] { "THE CURATOR", "Someone broke this kettle. Not for the kettle. For the sound it makes when it breaks. Fear is a language, and they are fluent." }},
        {"cur1_03", new[] { "THE CURATOR", "The chai-wallah gave what he had left to give. A daughter's life in a plastic shell. Evidence is never only evidence." }},
        {"cur1_04", new[] { "THE CURATOR", "A watcher who drops her badge is either careless or inviting you to follow. She did not look careless." }},
        {"cur1_05", new[] { "THE CURATOR", "Drivers are confessional. They hear the sentences people say to the air. If you had not asked the man who drove her what he heard, you have left a witness idling at the curb." }},
        {"cur1_06", new[] { "THE CURATOR", "Black cars are like bad thoughts. They follow you home and never use their indicators." }},
        {"cur1_07", new[] { "THE CURATOR", "You have been noticed. Somewhere in this city, your face is a file now. Files are patient. They wait in drawers and become warrants." }},
        {"cur1_08", new[] { "THE CURATOR", "Go on. The night is young and the kettle is broken. Both are your problem now." }},
        {"cur2_01", new[] { "THE CURATOR", "You have found the lie at the bottom of the city. It is small, isn't it? A date. A stamp. A signature that leans the wrong way." }},
        {"cur2_02", new[] { "THE CURATOR", "Empires fall on stationery." }},
        {"cur2_03", new[] { "THE CURATOR", "Nineteen forty-two. Nineteen sixty-five. Ten o'clock. History is a queue of paper, and someone has been jumping it." }},
        {"cur2_04", new[] { "THE CURATOR", "A locked drawer, opened with a grandmother's name. Sentiment is an excellent password. No one brute-forces it." }},
        {"cur2_05", new[] { "THE CURATOR", "The inspector signed for the truth and locked it in a cage. The question is not whether she is a thief. The question is what she intends to do with the stolen thing." }},
        {"cur2_06", new[] { "THE CURATOR", "Panditji asked you what matters more: the truth, or the people the truth protects. You answered. I heard you." }},
        {"cur2_07", new[] { "THE CURATOR", "I have ten thousand stories on these shelves. I can tell you which answer is true. I cannot tell you which one is kind. That is your department." }},
        {"cur2_08", new[] { "THE CURATOR", "Three doors. A cafe. A house. A woman in khaki. You cannot open all three. That is not cruelty. That is arithmetic." }},
        {"cur2_09", new[] { "THE CURATOR", "The call that summons you and the call that frightens you came in the same hour. One is a trap. One is a test. They may be the same thing." }},
        {"cur2_10", new[] { "THE CURATOR", "Choose the door that costs you something. The others are only corridors." }},
        {"cur2_11", new[] { "THE CURATOR", "And investigator, the next time we meet, you will have chosen your company. Choose it for the right reason, not the loud one." }},
        {"cur3_01", new[] { "THE CURATOR", "There you are. Still breathing. Still meddling. I am beginning to enjoy you." }},
        {"cur3_02", new[] { "THE CURATOR", "It is nearly four. The hour when cities confess." }},
        {"cur3_03", new[] { "THE CURATOR", "You have chosen your company. A builder who wanted to be good. A boy who wanted to be brave. A woman who wanted to be right. Whichever door you opened, you did not choose a saviour. You chose a witness. That is rarer." }},
        {"cur3_04", new[] { "THE CURATOR", "Every ally is a receipt. You will pay for them at dawn." }},
        {"cur3_05", new[] { "THE CURATOR", "You have collected them the way a drowning man collects driftwood. Good. Driftwood does not steer." }},
        {"cur3_06", new[] { "THE CURATOR", "At ten, a judge will ask what you can prove. Not what you feel. Not what you suspect. What you can put on a table and make him look at." }},
        {"cur3_07", new[] { "THE CURATOR", "Count your evidence, investigator. Then count it again. The difference between a rescue and a massacre is usually paperwork." }},
        {"cur3_08", new[] { "THE CURATOR", "And you have made a witness of a woman who has been running for her life. A witness is not a thing you carry. It is a person you spend." }},
        {"cur3_09", new[] { "THE CURATOR", "The next room is mine. There are three boxes on a table and a question in each. You will pretend to choose. We both know you have been choosing all night." }},
        {"cur3_10", new[] { "THE CURATOR", "After you." }},
        {"cur2_truth", new[] { "THE CURATOR", "You chose the truth. Clean. Cold. A sword is also clean." }},
        {"cur2_people", new[] { "THE CURATOR", "You chose the people. Warm. Necessary. A blanket can also smother." }},
        {"cur2_both", new[] { "THE CURATOR", "You chose both. Ambitious. The truest answers are the ones that cost the most to hold at once." }},
        {"cur3_raj", new[] { "THE CURATOR", "The builder wanted to be good and settled for useful. There is a difference, and he knows it now. He handed you six months of his own voice. Do you know what that costs a man? More than money." }},
        {"cur3_rohan", new[] { "THE CURATOR", "The boy lit the fuse and then tried to carry the bomb. Guilt makes soldiers of children. It also makes liars. He is not brave, your Rohan. He is sorry. Sometimes sorry is enough." }},
        {"cur3_reddy", new[] { "THE CURATOR", "The inspector lied to you for your own good. The rarest kind of lie. Treasure it. Also, check it. She built a case for six months while the city built a coffin." }},
        {"endG_01", new[] { "THE CURATOR", "Ah. There you are. On the other side." }},
        {"endG_02", new[] { "THE CURATOR", "You chose. The city will do the rest. It always does." }},
        {"endG_03", new[] { "THE CURATOR", "I have seen a thousand endings to this story. Justice. Sacrifice. Revolution. The names change. The bill does not." }},
        {"endG_04", new[] { "THE CURATOR", "Someone was saved. Something was spent. You learned the difference between the truth and the people it protects. That is more than most of my visitors manage." }},
        {"endG_05", new[] { "THE CURATOR", "The book is closed. The candle is out. The shelf has a new story on it." }},
        {"endG_06", new[] { "THE CURATOR", "And you, you have a new one to live." }},
        {"endG_07", new[] { "THE CURATOR", "I will see you in the next one." }},
        {"endJ_01", new[] { "THE CURATOR", "So. The courtroom. The deed. The gavel. You chose the clean ending." }},
        {"endJ_02", new[] { "THE CURATOR", "I must confess, I do not get many of these. Most of my stories end in blood or silence. This one ends in sunlight. How unusual." }},
        {"endJ_03", new[] { "THE CURATOR", "You proved that the courage of one can shelter the many. A textbook victory for righteousness. The sort of ending that makes children believe the world is fair." }},
        {"endJ_04", new[] { "THE CURATOR", "Enjoy it, investigator. Endings like this are rare, and rarer still are the people who deserve them." }},
        {"endJ_05", new[] { "THE CURATOR", "The candle is out. The book is closed. I will see you in the next one." }},
        {"endS_01", new[] { "THE CURATOR", "So. The girl lives. The evidence goes in alone. You chose the quiet ending." }},
        {"endS_02", new[] { "THE CURATOR", "You saved her. Congratulations. Was she worth five hundred families? I am not judging. Actually, I am. That is rather my job." }},
        {"endS_03", new[] { "THE CURATOR", "You built a sanctuary on graves and called it mercy. It will hold. For a while. Sanctuaries always hold until they don't." }},
        {"endS_04", new[] { "THE CURATOR", "She will spend the rest of her life wondering what would have happened if she had been brave enough to walk through those doors. You gave her that, too." }},
        {"endS_05", new[] { "THE CURATOR", "The candle is out. The book is closed. I will see you in the next one." }},
        {"endR_01", new[] { "THE CURATOR", "So. The press. The streets. The fire. You chose the loud ending." }},
        {"endR_02", new[] { "THE CURATOR", "I have many stories of revolution. They all end the same way. The people cheer. The hero weeps. The crowd goes home. The hero stays in the fire." }},
        {"endR_03", new[] { "THE CURATOR", "You gave them the truth. You took her peace. Freedom is a marvellous thing, and its price is always paid in a currency the crowd never sees." }},
        {"endR_04", new[] { "THE CURATOR", "Perhaps they will remember her name. Perhaps they will remember the noise. The city is fickle. The fire is not." }},
        {"endR_05", new[] { "THE CURATOR", "The candle is out. The book is closed. I will see you in the next one." }},
        {"flash1_01", new[] { "THE CURATOR", "Don't mind me. I am only here for the draft." }},
        {"flash1_02", new[] { "THE CURATOR", "You are looking for a page that has already been read. The question is not where the deed is. The question is who signed for it." }},
        {"flash1_03", new[] { "THE CURATOR", "Also, the desk upstairs is a poor lock with a good memory. Ask the calendar what it remembers." }},
        {"flash2_01", new[] { "THE CURATOR", "Left is a dead end. Right is a road. I know which one you want. It has better scenery." }},
        {"flash2_02", new[] { "THE CURATOR", "Tonight, be boring. Boring people live to testify." }},
        {"flash2_03", new[] { "THE CURATOR", "Mind the dumpster. It has opinions." }},
        {"end1_vo_dawn", new[] { "ARJUN (V.O.)", "Dawn. Shutters rising, temple bells, chai stoves. And outside the Municipal Court, Basti Nagar had come to watch." }},
        {"end1_lawyer", new[] { "DESHPANDE'S LAWYER", "Your Honour, the Renewal Project is a vision for a modern Chandnipur. The acquisition order of 1965 is entirely in order." }},
        {"end1_priya", new[] { "PRIYA KAPOOR", "Your Honour, I am Priya Kapoor, advocate for the residents of Basti Nagar. The acquisition order of 1965 is a forgery. This is the original file, with the forgers' signatures on it. And the original deed of 1942, now in Crime Branch custody, proves the land belongs to its residents, in perpetuity." }},
        {"end1_reddy", new[] { "INSPECTOR REDDY", "Inspector Sonal Reddy, Crime Branch. This is the original deed of 1942, taken from the Record Room into Crime Branch custody. And I have a warrant for the arrest of Councilor Meghna Deshpande, for fraud, forgery and criminal conspiracy." }},
        {"end1_raj", new[] { "RAJ MALHOTRA", "I am Raj Malhotra. I signed the Renewal contracts. And I have six months of recordings of the councilor planning this fraud. I will play them for the court." }},
        {"end1_rohan", new[] { "ROHAN KAPOOR", "I'm Rohan Kapoor. I was an intern at the Municipal Office. These internal emails prove the forgery was known, and approved, at the highest level." }},
        {"end1_judge", new[] { "THE JUDGE", "The Chandnipur Renewal Project is hereby stayed, pending a full investigation into the land records. The residents of Basti Nagar shall not be displaced." }},
        {"end1_vo_end", new[] { "ARJUN (V.O.)", "In Chandnipur, the truth is a fragile thing. But sometimes one person with a spine of steel and a folder full of evidence can crack the whole thing open. Today was one of those days." }},
        {"end1_curator", new[] { "THE CURATOR", "I must confess, I don't get many of these. Most of my stories end in blood, or silence. This one ends in sunlight. Bravo. A rare, happy ending for my collection." }},
        {"end2_vo", new[] { "ARJUN (V.O.)", "I walked into the Municipal Court alone. A few lawyers, a bored clerk, and the councilor in the front row, looking bored too." }},
        {"end2_lawyer", new[] { "DESHPANDE'S LAWYER", "Your Honour, these documents were allegedly stolen from a government facility by a fugitive. The chain of custody is broken. Without the person who obtained them, this evidence is inadmissible." }},
        {"end2_kamala", new[] { "KAMALA KAPOOR", "Your Honour, I am Kamala Kapoor, Priya's mother. I can testify that my daughter has been threatened, that our home was broken into by agents of the councilor, and that the documents my daughter found are genuine. I may not be a lawyer, but I am a teacher, and I know the difference between truth and lies." }},
        {"end2_vikram", new[] { "VIKRAM SAHU", "I am Vikram Sahu. I sell chai near the market. Two men broke my kettle and told me to keep quiet. I am not quiet any more." }},
        {"end2_judge", new[] { "THE JUDGE", "This court cannot rule without proper standing. But it orders a full investigation into the land records, and stays the eviction until that investigation is complete." }},
        {"end2_vo_end", new[] { "ARJUN (V.O.)", "Not every battle ends with a bang. Some end with a whisper. A judge's order, a mother's courage. The truth is out there now, but it's fragile. It needs protecting." }},
        {"end2_curator", new[] { "THE CURATOR", "You saved the girl. Congratulations. Was she worth five hundred families? I'm not judging. Actually, I am. That's rather my job." }},
        {"end3_priya_1", new[] { "PRIYA KAPOOR", "Once this is out, there's no taking it back. Deshpande will come after us with everything she has." }},
        {"end3_arjun_1", new[] { "ARJUN", "She'll come after us anyway. At least this way, the whole city will be watching." }},
        {"end3_priya_2", new[] { "PRIYA KAPOOR", "The truth is out. But truth without a courtroom is just noise, until enough people listen. I hope they're listening. Did we do the right thing?" }},
        {"end3_arjun_2", new[] { "ARJUN", "Ask me in a year." }},
        {"a5r_reporter", new[] { "REPORTER", "Six months of recordings. The original deed. Oh god. This is real." }},
        {"a5r_news", new[] { "TELEVISION", "Breaking news from Chandnipur. Documents and recordings released overnight allege that the land order behind the Renewal Project was forged in nineteen sixty five, and that the councilor knew." }},
        {"end3_curator", new[] { "THE CURATOR", "I have many stories of revolution in my collection. They all end the same way. The people cheering, and the hero weeping. The crowd goes home. The hero stays in the fire." }},
    };

    public static string Speaker(string id) { string[] l; return lines.TryGetValue(id, out l) ? l[0] : ""; }
    public static string Text(string id) { string[] l; return lines.TryGetValue(id, out l) ? l[1] : id; }
}
